"""Value types of the MTL type system."""
import re

INT = "int"
FLOAT = "float"
STRING = "string"
BOOL = "bool"
TIMESTAMP = "timestamp"

NUMERIC = frozenset({INT, FLOAT})


def is_numeric(t):
    return t in NUMERIC


def numeric_result(*types):
    """Result type of an int/float operation (int only if all operands are int)."""
    return INT if all(t == INT for t in types) else FLOAT


def comparable(a, b, op):
    """Whether values of types a and b may be compared with operator op."""
    if is_numeric(a) and is_numeric(b):
        return True
    if a != b:
        return False
    if a in (STRING, TIMESTAMP):
        return True
    if a == BOOL:
        return op in ("==", "!=")
    return False


_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$")
_BOOLS = {"true": True, "false": False}


def looks_like(text, t):
    """Whether stripped text is a valid literal of int, float or bool type."""
    if t == INT:
        return bool(_INT_RE.match(text))
    if t == FLOAT:
        return bool(_FLOAT_RE.match(text))
    if t == BOOL:
        return text.lower() in _BOOLS
    raise AssertionError(f"no text form check for {t}")


def parse_text(text, t):
    """Parse stripped text as an int, float or bool; raise ValueError when invalid."""
    if not looks_like(text, t):
        raise ValueError(f"not a valid {t}")
    if t == INT:
        return int(text)
    if t == FLOAT:
        value = float(text)
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError("not a finite number")
        return value
    return _BOOLS[text.lower()]
"""Explicit `cast(expr as type)` conversions: which are legal and how values convert."""
import math
from datetime import timedelta, timezone

from . import dtypes
from .errors import RuntimeFailure
from .timeutil import EPOCH, ONE_MICROSECOND, TimestampParser, format_utc

_ILLEGAL = {
    (dtypes.BOOL, dtypes.TIMESTAMP),
    (dtypes.TIMESTAMP, dtypes.BOOL),
}

# Parser used for string -> timestamp casts; the CLI installs one honouring --tz.
_timestamp_parser = TimestampParser(timezone.utc)


def set_timestamp_parser(parser):
    global _timestamp_parser
    _timestamp_parser = parser


def allowed(source, target):
    return (source, target) not in _ILLEGAL


def convert(value, source, target, line):
    """Convert a non-null value of type `source` to `target`; failures are runtime errors."""
    if value is None:
        return None
    if source == target:
        return value
    try:
        result = _convert(value, source, target)
    except (ValueError, OverflowError) as exc:
        raise RuntimeFailure(f"line {line}: cannot cast {_show(value)} "
                             f"from {source} to {target}: {exc}") from exc
    if isinstance(result, float) and not math.isfinite(result):
        raise RuntimeFailure(f"line {line}: cast produced a non-finite number")
    return result


def _convert(value, source, target):
    if target == dtypes.STRING:
        if source == dtypes.BOOL:
            return "true" if value else "false"
        if source == dtypes.TIMESTAMP:
            return format_utc(value)
        if source == dtypes.FLOAT:
            return repr(value)
        return str(value)
    if source == dtypes.STRING:
        if target == dtypes.TIMESTAMP:
            return _timestamp_parser.parse(value)
        return dtypes.parse_text(value.strip(), target)
    if target == dtypes.INT:
        if source == dtypes.TIMESTAMP:
            return (value - EPOCH) // timedelta(seconds=1)
        if source == dtypes.FLOAT:
            return math.trunc(value)
        return int(value)
    if target == dtypes.FLOAT:
        if source == dtypes.TIMESTAMP:
            return ((value - EPOCH) // ONE_MICROSECOND) / 1_000_000
        return float(value)
    if target == dtypes.BOOL:
        return value != 0
    if target == dtypes.TIMESTAMP:
        return EPOCH + timedelta(seconds=value)
    raise AssertionError(f"unhandled cast {source} -> {target}")


def _show(value):
    return repr(value) if isinstance(value, str) else str(value)
"""Timestamp parsing, timezone handling, epoch arithmetic and UTC formatting."""
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)
ONE_MICROSECOND = timedelta(microseconds=1)


def resolve_timezone(name):
    """Return a tzinfo for an IANA name; raise ValueError when unknown."""
    if name in ("UTC", "Z", "utc"):
        return timezone.utc
    try:
        return ZoneInfo(name)
    except (ZoneInfoNotFoundError, ValueError, OSError) as exc:
        raise ValueError(f"unknown timezone '{name}'") from exc


class TimestampParser:
    """Parses raw timestamp strings into timezone-aware UTC datetimes."""

    def __init__(self, default_tz, fmt=None):
        self.default_tz = default_tz
        self.fmt = fmt

    def parse(self, text):
        """Parse text; raise ValueError when it is not a valid timestamp."""
        raw = text.strip()
        if not raw:
            raise ValueError("empty timestamp")
        if self.fmt is not None:
            dt = datetime.strptime(raw, self.fmt)
        else:
            dt = _parse_iso(raw)
        if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
            dt = dt.replace(tzinfo=self.default_tz)
        return dt.astimezone(timezone.utc)


def _parse_iso(raw):
    candidate = raw
    if candidate[-1] in "zZ":
        candidate = candidate[:-1] + "+00:00"
    return datetime.fromisoformat(candidate)


def epoch_micros(dt):
    return (dt - EPOCH) // ONE_MICROSECOND


def from_epoch_micros(micros):
    return EPOCH + timedelta(microseconds=micros)


def format_utc(dt):
    """ISO 8601 in UTC with a trailing Z."""
    dt = dt.astimezone(timezone.utc)
    if dt.microsecond:
        return dt.strftime("%Y-%m-%dT%H:%M:%S.%f") + "Z"
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "Z"
"""Row-level evaluation of type-checked expressions (nulls propagate SQL-style).

Post-aggregation expressions are evaluated with a frame: the ordered list of
output rows and the current index, which lag()/lead() navigate.
"""
import math
import operator

from . import casts, dtypes, functions
from .ast_nodes import Binary, Call, Cast, ColumnRef, InExpr, Literal, Unary
from .errors import RuntimeFailure

_COMPARE = {
    "<": operator.lt, "<=": operator.le, ">": operator.gt,
    ">=": operator.ge, "==": operator.eq, "!=": operator.ne,
}


def evaluate(expr, row, frame=None):
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return row[expr.name]
    if isinstance(expr, Binary):
        return _eval_binary(expr, row, frame)
    if isinstance(expr, Unary):
        value = evaluate(expr.operand, row, frame)
        if value is None:
            return None
        if expr.op == "!":
            return not value
        return -value if expr.op == "-" else value
    if isinstance(expr, InExpr):
        haystack = evaluate(expr.haystack, row, frame)
        if haystack is None:
            return None
        return evaluate(expr.needle, row, frame) in haystack
    if isinstance(expr, Cast):
        value = evaluate(expr.operand, row, frame)
        return casts.convert(value, expr.operand.type, expr.target, expr.line)
    if isinstance(expr, Call):
        return _check_finite(_eval_call(expr, row, frame), expr)
    raise AssertionError(f"unknown expression node {expr!r}")


def _eval_call(expr, row, frame):
    name = expr.name
    if name == "param":
        return expr.value
    if name == "coalesce":
        value = evaluate(expr.args[0], row, frame)
        if value is None or (isinstance(value, float) and math.isnan(value)):
            return evaluate(expr.args[1], row, frame)
        return value
    if name in functions.WINDOW_FUNCTIONS:
        return _eval_offset(expr, row, frame)
    args = [evaluate(a, row, frame) for a in expr.args]
    return functions.call(name, args)


def _eval_offset(expr, row, frame):
    """lag(expr, k) / lead(expr, k): the value of expr k rows before/after this one."""
    k = evaluate(expr.args[1], row, frame)
    if k is None or k <= 0:
        raise RuntimeFailure(f"line {expr.line}: {expr.name}() offset must be a positive "
                             f"integer, got {k}")
    rows, index = frame
    target = index - k if expr.name == "lag" else index + k
    if not 0 <= target < len(rows):
        return None
    return evaluate(expr.args[0], rows[target], (rows, target))


def _eval_binary(expr, row, frame):
    op = expr.op
    if op == "&":
        left = evaluate(expr.left, row, frame)
        if left is False:
            return False
        right = evaluate(expr.right, row, frame)
        if right is False:
            return False
        return None if left is None or right is None else True
    if op == "|":
        left = evaluate(expr.left, row, frame)
        if left is True:
            return True
        right = evaluate(expr.right, row, frame)
        if right is True:
            return True
        return None if left is None or right is None else False

    left = evaluate(expr.left, row, frame)
    right = evaluate(expr.right, row, frame)
    if left is None or right is None:
        return None
    if op in _COMPARE:
        return _COMPARE[op](left, right)
    return _check_finite(_arithmetic(op, left, right, expr), expr)


def _arithmetic(op, left, right, expr):
    try:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if right == 0:
            raise RuntimeFailure(f"line {expr.line}: division by zero")
        if op == "/":
            return left / right
        return left % right
    except OverflowError as exc:
        raise RuntimeFailure(f"line {expr.line}: numeric overflow") from exc


def _check_finite(value, expr):
    if isinstance(value, float) and not math.isfinite(value):
        raise RuntimeFailure(f"line {expr.line}: expression produced a non-finite number")
    if expr.type == dtypes.FLOAT and isinstance(value, int) and not isinstance(value, bool):
        try:
            return float(value)
        except OverflowError as exc:
            raise RuntimeFailure(f"line {expr.line}: numeric overflow") from exc
    return value
"""Scalar transform functions: arity, type signatures and implementations."""
from decimal import ROUND_HALF_UP, Context, Decimal, InvalidOperation

from . import dtypes
from .errors import TypeCheckError

# name -> (min_args, max_args)
ARITY = {
    "len": (1, 1),
    "day": (1, 1),
    "month": (1, 1),
    "year": (1, 1),
    "round": (1, 2),
    "starts_with": (2, 2),
    "ends_with": (2, 2),
    "contains": (2, 2),
    "coalesce": (2, 2),
    # Context-dependent: typed by the checker, evaluated by the evaluator.
    "param": (1, 1),
    "lag": (2, 2),
    "lead": (2, 2),
}

STRING_PREDICATES = ("starts_with", "ends_with", "contains")
WINDOW_FUNCTIONS = ("lag", "lead")


def result_type(name, arg_types, line):
    """Validate argument types for a call; return the result type."""
    def fail(expected):
        got = ", ".join(arg_types)
        raise TypeCheckError(f"line {line}: {name}() expects {expected}, got ({got})")

    if name == "len":
        if arg_types[0] != dtypes.STRING:
            fail("a string")
        return dtypes.INT
    if name in ("day", "month", "year"):
        if arg_types[0] != dtypes.TIMESTAMP:
            fail("a timestamp")
        return dtypes.INT
    if name == "round":
        if not dtypes.is_numeric(arg_types[0]):
            fail("a number")
        if len(arg_types) == 2 and arg_types[1] != dtypes.INT:
            fail("an integer number of digits")
        return arg_types[0]
    if name in STRING_PREDICATES:
        if arg_types != [dtypes.STRING, dtypes.STRING]:
            fail("two strings")
        return dtypes.BOOL
    if name == "coalesce":
        a, b = arg_types
        if a == b:
            return a
        if dtypes.is_numeric(a) and dtypes.is_numeric(b):
            return dtypes.FLOAT
        fail("two arguments of the same type")
    raise AssertionError(f"unknown function {name}")


def call(name, args):
    """Invoke a transform; null arguments yield null."""
    if any(a is None for a in args):
        return None
    if name == "len":
        return len(args[0])
    if name == "day":
        return args[0].day
    if name == "month":
        return args[0].month
    if name == "year":
        return args[0].year
    if name == "round":
        digits = args[1] if len(args) > 1 else 0
        return round_half_away(args[0], digits)
    if name == "starts_with":
        return args[0].startswith(args[1])
    if name == "ends_with":
        return args[0].endswith(args[1])
    if name == "contains":
        return args[1] in args[0]
    raise AssertionError(f"unknown function {name}")


_DECIMAL_CTX = Context(prec=1000)


def round_half_away(value, digits):
    """Round to `digits` decimal places, ties away from zero."""
    if isinstance(value, int) and not isinstance(value, bool):
        if digits >= 0:
            return value
        dec = Decimal(value)
    else:
        dec = Decimal(repr(value))
    if digits > 400 or digits < -400:
        return value if digits > 0 else type(value)(0)
    quantum = Decimal(1).scaleb(-digits)
    try:
        rounded = dec.quantize(quantum, rounding=ROUND_HALF_UP, context=_DECIMAL_CTX)
    except InvalidOperation:
        return value
    if isinstance(value, int):
        return int(rounded)
    return float(rounded)
"""Aggregate functions over a bucket of rows (nulls are ignored, empty input -> null)."""
import math

from .errors import RuntimeFailure


def _sum(values):
    return sum(values)


def _average(values):
    return sum(values) / len(values)


def _median(values):
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2


def _var(values):
    mean = sum(values) / len(values)
    return sum((v - mean) * (v - mean) for v in values) / len(values)


def _std(values):
    return math.sqrt(_var(values))


_FUNCTIONS = {
    "sum": _sum,
    "average": _average,
    "median": _median,
    "var": _var,
    "std": _std,
    "min": min,
    "max": max,
}


def compute(item, rows):
    """Compute one aggregate item over a list of row dicts."""
    if item.func == "count":
        if item.column is None:
            return len(rows)
        return sum(1 for r in rows if r[item.column] is not None)
    values = [r[item.column] for r in rows if r[item.column] is not None]
    if not values:
        return None
    try:
        result = _FUNCTIONS[item.func](values)
    except (OverflowError, ValueError) as exc:
        raise RuntimeFailure(f"{item.func}({item.column}) failed: {exc}") from exc
    if isinstance(result, float) and not math.isfinite(result):
        raise RuntimeFailure(f"{item.func}({item.column}) produced a non-finite number")
    return result
"""Normalization (row ordering, key ordering) and deterministic JSON serialization."""
import json
import math
from datetime import datetime

from .errors import RuntimeFailure
from .timeutil import format_utc


def build_document(program, buckets):
    """Produce the JSON-ready value from normalized-order buckets.

    Keys: window bounds, group keys, aggregate aliases (sorted), then
    post-aggregation calcs (sorted).
    """
    aliases = sorted(item.alias for item in program.aggregate.items)
    calc_names = sorted(calc.name for calc in program.post_calcs)
    group_cols = program.group_columns
    windowed = program.window is not None

    if not group_cols and not windowed:
        bucket = buckets[0]
        record = {alias: _json_value(bucket.values[alias]) for alias in aliases}
        for name in calc_names:
            record[name] = _json_value(bucket.calcs[name])
        return record

    records = []
    for bucket in buckets:
        record = {}
        if windowed:
            record["window_start"] = format_utc(bucket.window_start)
            record["window_end"] = format_utc(bucket.window_end)
        for col, value in zip(group_cols, bucket.group_key):
            record[col] = _json_value(value)
        for alias in aliases:
            record[alias] = _json_value(bucket.values[alias])
        for name in calc_names:
            record[name] = _json_value(bucket.calcs[name])
        records.append(record)
    return records


def _json_value(value):
    if isinstance(value, datetime):
        return format_utc(value)
    if isinstance(value, float) and not math.isfinite(value):
        raise RuntimeFailure("result contains a non-finite number")
    return value


def serialize(document):
    return json.dumps(document, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
"""Pipeline parameters: merging DSL defaults with --param values into typed constants."""
from . import dtypes
from .errors import DSLSyntaxError, IOFailure, TypeCheckError


class ParamValue:
    def __init__(self, name, param_type, value):
        self.name = name
        self.type = param_type
        self.value = value


def parse_cli_params(items):
    """Turn ['key=value', ...] into a dict; the last duplicate wins."""
    values = {}
    for item in items:
        key, sep, value = item.partition("=")
        key = key.strip()
        if not sep or not key:
            raise IOFailure(f"invalid --param '{item}': expected key=value")
        values[key] = value
    return values


def check_provided(decls, cli_values, strict=False):
    """DSL errors: parameters without a default that were not supplied (and, in
    strict mode, supplied parameters the pipeline does not declare)."""
    missing = [d.name for d in decls if d.default is None and d.name not in cli_values]
    if missing:
        raise DSLSyntaxError(f"missing value for parameter(s) without default: "
                             f"{', '.join(missing)}")
    if strict:
        declared = {d.name for d in decls}
        unknown = sorted(k for k in cli_values if k not in declared)
        if unknown:
            raise DSLSyntaxError(f"undeclared parameter(s) supplied: {', '.join(unknown)}")


def resolve(decls, cli_values, ts_parser):
    """Return name -> ParamValue; values that do not fit their type are type errors."""
    resolved = {}
    for decl in decls:
        param_type = decl.type
        if param_type is None:
            param_type = decl.default.type if decl.default is not None else dtypes.STRING
        default = None
        if decl.default is not None:
            default = _from_literal(decl, param_type, ts_parser)
        if decl.name in cli_values:
            value = _from_text(decl.name, param_type, cli_values[decl.name], ts_parser)
        else:
            value = default
        resolved[decl.name] = ParamValue(decl.name, param_type, value)
    return resolved


def _from_literal(decl, param_type, ts_parser):
    lit = decl.default
    if lit.type == param_type:
        return lit.value
    if param_type == dtypes.FLOAT and lit.type == dtypes.INT:
        return float(lit.value)
    if param_type == dtypes.TIMESTAMP and lit.type == dtypes.STRING:
        try:
            return ts_parser.parse(lit.value)
        except ValueError as exc:
            raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' is not "
                                 f"a valid timestamp: {exc}") from exc
    raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' has type "
                         f"{lit.type}, expected {param_type}")


def _from_text(name, param_type, text, ts_parser):
    if param_type == dtypes.STRING:
        return text
    try:
        if param_type == dtypes.TIMESTAMP:
            return ts_parser.parse(text)
        return dtypes.parse_text(text.strip(), param_type)
    except ValueError as exc:
        raise TypeCheckError(f"--param {name}={text!r} is not a valid {param_type}: "
                             f"{exc}") from exc
"""Resolution of schema blocks: inheritance, type overrides and calculated-field order."""
import copy

from . import dtypes
from .ast_nodes import ColumnRef
from .errors import DSLSyntaxError, TypeCheckError
from .typecheck import walk


class ResolvedField:
    """A schema field after inheritance; `visible` are the names its expression may use."""

    def __init__(self, name, field_type, expr, line, visible):
        self.name = name
        self.type = field_type
        self.expr = expr
        self.line = line
        self.visible = visible

    @property
    def is_calculated(self):
        return self.expr is not None


class ResolvedSchema:
    def __init__(self, name, fields):
        self.name = name
        self.fields = fields  # name -> ResolvedField, in declaration order
        self.calc_order = _calc_order(name, fields)

    @property
    def types(self):
        return {name: f.type for name, f in self.fields.items()}

    @property
    def physical(self):
        return {name: f.type for name, f in self.fields.items() if not f.is_calculated}


def override_allowed(old, new):
    """Same type, or numeric widening int -> float."""
    return old == new or (old == dtypes.INT and new == dtypes.FLOAT)


def resolve_all(decls):
    """Resolve every schema declaration; returns name -> ResolvedSchema."""
    resolved = {}
    for name in decls:
        _resolve(name, decls, resolved, [])
    return resolved


def _resolve(name, decls, resolved, stack):
    if name in resolved:
        return resolved[name]
    if name in stack:
        chain = " -> ".join(stack[stack.index(name):] + [name])
        raise DSLSyntaxError(f"circular schema inheritance: {chain}")
    decl = decls[name]
    fields = {}
    if decl.base is not None:
        if decl.base not in decls:
            raise DSLSyntaxError(f"line {decl.line}: schema '{name}' extends unknown "
                                 f"schema '{decl.base}'")
        base = _resolve(decl.base, decls, resolved, stack + [name])
        for fname, f in base.fields.items():
            fields[fname] = ResolvedField(f.name, f.type, copy.deepcopy(f.expr), f.line, f.visible)

    visible = set(fields)
    for f in decl.fields:
        if f.expr is not None:
            _check_references(f, visible, name)
        inherited = fields.get(f.name)
        if inherited is not None and not override_allowed(inherited.type, f.type):
            raise TypeCheckError(f"line {f.line}: schema '{name}' cannot override field "
                                 f"'{f.name}' from {inherited.type} to {f.type}")
        fields[f.name] = ResolvedField(f.name, f.type, f.expr, f.line, frozenset(visible))
        visible.add(f.name)

    result = ResolvedSchema(name, fields)
    resolved[name] = result
    return result


def _check_references(field, visible, schema_name):
    for node in walk(field.expr):
        if isinstance(node, ColumnRef) and node.name not in visible:
            raise DSLSyntaxError(f"line {field.line}: calculated field '{field.name}' in schema "
                                 f"'{schema_name}' references unknown or later-declared field "
                                 f"'{node.name}'")


def _calc_order(schema_name, fields):
    """Calculated fields ordered so each comes after the calculated fields it uses."""
    order = []
    state = {}

    def visit(f):
        mark = state.get(f.name)
        if mark == "done":
            return
        if mark == "active":
            raise DSLSyntaxError(f"line {f.line}: calculated field '{f.name}' in schema "
                                 f"'{schema_name}' depends on itself")
        state[f.name] = "active"
        for node in walk(f.expr):
            if isinstance(node, ColumnRef):
                dep = fields.get(node.name)
                if dep is not None and dep.is_calculated:
                    visit(dep)
        state[f.name] = "done"
        order.append(f)

    for f in fields.values():
        if f.is_calculated:
            visit(f)
    return order

