            stack.append(node.operand)


def check_names(expr, visible, params, line, aliases=(), later=(), allow_window=False):
    """Report structural name errors; unknown plain columns are left to `infer`."""
    for node in walk(expr):
        if isinstance(node, ColumnRef) and node.name not in visible:
            if node.name in later:
                raise DSLSyntaxError(f"line {line}: '{node.name}' is referenced before "
                                     "it is declared")
            if node.name in aliases:
                raise DSLSyntaxError(f"line {line}: aggregate alias '{node.name}' cannot be "
                                     "used before aggregation")
        elif isinstance(node, Call):
            if node.name == "param" and node.args[0].value not in params:
                raise DSLSyntaxError(f"line {line}: unknown parameter '{node.args[0].value}'")
            if node.name in functions.WINDOW_FUNCTIONS and not allow_window:
                raise DSLSyntaxError(f"line {line}: {node.name}() is only allowed in "
                                     "@stage(post_agg) calcs")


def infer(expr, schema, params=None):
    expr.type = _infer(expr, schema, params or {})
    return expr.type


def _infer(expr, schema, params):
    if isinstance(expr, Literal):
        return expr.type
    if isinstance(expr, ColumnRef):
        if expr.name not in schema:
            raise TypeCheckError(f"line {expr.line}: unknown column '{expr.name}'")
        return schema[expr.name]
    if isinstance(expr, Unary):
        t = infer(expr.operand, schema, params)
        if expr.op == "!":
            if t != dtypes.BOOL:
                raise TypeCheckError(f"line {expr.line}: '!' requires a boolean operand, got {t}")
            return dtypes.BOOL
        if not dtypes.is_numeric(t):
            raise TypeCheckError(f"line {expr.line}: unary '{expr.op}' requires a number, got {t}")
        return t
    if isinstance(expr, Binary):
        return _infer_binary(expr, schema, params)
    if isinstance(expr, InExpr):
        return _infer_in(expr, schema, params)
    if isinstance(expr, Cast):
        source = infer(expr.operand, schema, params)
        if not casts.allowed(source, expr.target):
            raise TypeCheckError(f"line {expr.line}: cannot cast {source} to {expr.target}")
        return expr.target
    if isinstance(expr, Call):
        return _infer_call(expr, schema, params)
    raise AssertionError(f"unknown expression node {expr!r}")


def _infer_call(expr, schema, params):
    if expr.name == "param":
        name = expr.args[0].value
        if name not in params:
            raise DSLSyntaxError(f"line {expr.line}: unknown parameter '{name}'")
        expr.value = params[name].value
        return params[name].type
    arg_types = [infer(a, schema, params) for a in expr.args]
    if expr.name in functions.WINDOW_FUNCTIONS:
        if arg_types[1] != dtypes.INT:
            raise TypeCheckError(f"line {expr.line}: {expr.name}() offset must be an int, "
                                 f"got {arg_types[1]}")
        return arg_types[0]
    return functions.result_type(expr.name, arg_types, expr.line)


def _infer_binary(expr, schema, params):
    lt = infer(expr.left, schema, params)
    rt = infer(expr.right, schema, params)
    op = expr.op
    if op in LOGICAL_OPS:
        if lt != dtypes.BOOL or rt != dtypes.BOOL:
            raise TypeCheckError(f"line {expr.line}: '{op}' requires boolean operands, "
                                 f"got {lt} and {rt}")
        return dtypes.BOOL
    if op in COMPARISON_OPS:
        if not dtypes.comparable(lt, rt, op):
            raise TypeCheckError(f"line {expr.line}: cannot compare {lt} with {rt} using '{op}'")
        return dtypes.BOOL
    if op in ARITHMETIC_OPS:
        if not (dtypes.is_numeric(lt) and dtypes.is_numeric(rt)):
            raise TypeCheckError(f"line {expr.line}: '{op}' requires numeric operands, "
                                 f"got {lt} and {rt}")
        if op == "/":
            return dtypes.FLOAT
        return dtypes.numeric_result(lt, rt)
    raise AssertionError(f"unknown operator {op}")


def _infer_in(expr, schema, params):
    nt = infer(expr.needle, schema, params)
    ht = infer(expr.haystack, schema, params)
    if not (isinstance(expr.needle, Literal) and nt == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: left side of 'in' must be a string literal")
    if not (isinstance(expr.haystack, ColumnRef) and ht == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: right side of 'in' must be a string column")
    return dtypes.BOOL
"""AST node definitions for MTL expressions and statements.

Expression nodes carry a `type` attribute that the type checker fills in.
"""


class Expr:
    type = None


class Literal(Expr):
    def __init__(self, value, value_type):
        self.value = value
        self.type = value_type


class ColumnRef(Expr):
    def __init__(self, name, line):
        self.name = name
        self.line = line


class Unary(Expr):
    def __init__(self, op, operand, line):
        self.op = op
        self.operand = operand
        self.line = line


class Binary(Expr):
    def __init__(self, op, left, right, line):
        self.op = op
        self.left = left
        self.right = right
        self.line = line


class InExpr(Expr):
    """`needle in haystack`: substring test."""

    def __init__(self, needle, haystack, line):
        self.needle = needle
        self.haystack = haystack
        self.line = line


class Call(Expr):
    def __init__(self, name, args, line):
        self.name = name
        self.args = args
        self.line = line


class Cast(Expr):
    """`cast(expr as type)`: explicit conversion."""

    def __init__(self, operand, target, line):
        self.operand = operand
        self.target = target
        self.line = line


class Filter:
    def __init__(self, predicate, line):
        self.predicate = predicate
        self.line = line


class Apply:
    def __init__(self, expr, column, line):
        self.expr = expr
        self.column = column
        self.line = line


class GroupBy:
    def __init__(self, columns, line):
        self.columns = columns
        self.line = line


class Window:
    """A tumbling window; `param` names a parameter supplying the duration instead."""

    def __init__(self, amount, unit, seconds, line, param=None):
        self.amount = amount
        self.unit = unit
        self.seconds = seconds
        self.line = line
        self.param = param


class AggItem:
    def __init__(self, func, column, alias, line):
        self.func = func
        self.column = column  # None means '*'
        self.alias = alias
        self.line = line


class Aggregate:
    def __init__(self, items, line):
        self.items = items
        self.line = line


PRE = "pre"
POST_AGG = "post_agg"


class Calc:
    """`calc name = expr : type @stage(stage)`."""

    def __init__(self, name, expr, declared_type, stage, line):
        self.name = name
        self.expr = expr
        self.declared_type = declared_type
        self.stage = stage
        self.line = line


class FieldDecl:
    """A schema field: physical when `expr` is None, otherwise calculated (pre-stage)."""

    def __init__(self, name, field_type, expr, line):
        self.name = name
        self.type = field_type
        self.expr = expr
        self.line = line


class SchemaDecl:
    def __init__(self, name, base, fields, line):
        self.name = name
        self.base = base
        self.fields = fields
        self.line = line


class ParamDecl:
    """A pipeline parameter; `type` and `default` (a Literal) are both optional."""

    def __init__(self, name, param_type, default, line):
        self.name = name
        self.type = param_type
        self.default = default
        self.line = line


class Program:
    """A parsed pipeline: ordered row operations plus the grouping/aggregation spec.

    A program read from a bare statement file has no schema (its typing
    environment is the CSV header); one read from a `pipeline` block names
    the schema it uses and may declare parameters.
    """

    def __init__(self, row_ops, group_by, window, aggregate, calcs=(),
                 params=(), schema_name=None, schemas=None, name=None):
        self.row_ops = row_ops
        self.group_by = group_by
        self.window = window
        self.aggregate = aggregate
        self.calcs = list(calcs)
        self.params = list(params)
        self.schema_name = schema_name
        self.schemas = schemas or {}
        self.name = name

    @property
    def pre_calcs(self):
        return [c for c in self.calcs if c.stage == PRE]

    @property
    def post_calcs(self):
        return [c for c in self.calcs if c.stage == POST_AGG]

    @property
    def group_columns(self):
        return self.group_by.columns if self.group_by else []
"""Recursive-descent parser turning DSL source into a Program."""
